class Solution:
    def sufficientSubset(self, root, limit):
        def best(node, s):
            if not node.left and not node.right:
                return s + node.val
            m = float('-inf')
            if node.left:
                m = max(m, best(node.left, s + node.val))
            if node.right:
                m = max(m, best(node.right, s + node.val))
            return m

        bad = set()
        def mark(node):
            if not node:
                return
            if best(node, 0) < limit:
                bad.add(id(node))
            mark(node.left)
            mark(node.right)
        mark(root)

        def build(node):
            if not node or id(node) in bad:
                return None
            node.left = build(node.left)
            node.right = build(node.right)
            return node
        return build(root)

