public:
    long long best(TreeNode* node, long long s, int limit) {
        s += node->val;
        if (!node->left && !node->right) return s;
        long long m = LLONG_MIN;
        if (node->left) m = max(m, best(node->left, s, limit));
        if (node->right) m = max(m, best(node->right, s, limit));
        return m;
    }
    TreeNode* sufficientSubset(TreeNode* root, int limit) {
        unordered_set<TreeNode*> bad;
        function<void(TreeNode*)> mark = [&](TreeNode* n) {
            if (!n) return;
            if (best(n, 0, limit) < limit) bad.insert(n);
            mark(n->left); mark(n->right);
        };
        mark(root);
        function<TreeNode*(TreeNode*)> build = [&](TreeNode* n) -> TreeNode* {
            if (!n || bad.count(n)) return nullptr;
            n->left = build(n->left);
            n->right = build(n->right);
            return n;
        };
        return build(root);
    }
};

