class Solution {
    private Set<TreeNode> bad = new HashSet<>();
    private int limit;

    private long best(TreeNode node, long s) {
        s += node.val;
        if (node.left == null && node.right == null) return s;
        long m = Long.MIN_VALUE;
        if (node.left != null) m = Math.max(m, best(node.left, s));
        if (node.right != null) m = Math.max(m, best(node.right, s));
        return m;
    }

    public TreeNode sufficientSubset(TreeNode root, int limit) {
        this.limit = limit;
        mark(root);
        return build(root);
    }

    private void mark(TreeNode n) {
        if (n == null) return;
        if (best(n, 0) < limit) bad.add(n);
        mark(n.left); mark(n.right);
    }

    private TreeNode build(TreeNode n) {
        if (n == null || bad.contains(n)) return null;
        n.left = build(n.left);
        n.right = build(n.right);
        return n;
    }
}

