class Solution:
    def sufficientSubset(self, root: Optional[TreeNode], limit: int) -> Optional[TreeNode]:
        def dfs(node, s):
            if not node:
                return None
            t = s + node.val
            if not node.left and not node.right:
                return node if t >= limit else None
            node.left = dfs(node.left, t)
            node.right = dfs(node.right, t)
            if not node.left and not node.right:
                return node if t >= limit else None
            return node
        return dfs(root, 0)

